def solve(nums, k):
    def merge_sort_kth(arr, k):
        if len(arr) <= 1:
            return arr[0], arr  # (k-th element, sorted array)

        mid = len(arr) // 2
        left_val, left_sorted = merge_sort_kth(arr[:mid], k)
        right_val, right_sorted = merge_sort_kth(arr[mid:], k)

        merged = []
        i = j = 0
        while i < len(left_sorted) and j < len(right_sorted):
            if left_sorted[i] <= right_sorted[j]:
                merged.append(left_sorted[i])
                i += 1
            else:
                merged.append(right_sorted[j])
                j += 1
        merged.extend(left_sorted[i:])
        merged.extend(right_sorted[j:])

        if k <= len(merged):
            return merged[k - 1], merged
        else:
            return merged[-1], merged

    return merge_sort_kth(nums, k)[0]

