            left_size = node.left.size if node.left else 0
            if k == left_size + 1:
                return node.val
            elif k <= left_size:
                node = node.left
            else:
                k -= left_size + 1
                node = node.right
        return None

    root = None
    for num in nums:
        root = merge(root, TreapNode(num))
