    class FenwickTree:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 2)
        def update(self, index, delta=1):
            while index <= self.n:
                self.tree[index] += delta
                index += index & -index
        def query(self, index):
            res = 0
            while index > 0:
                res += self.tree[index]
                index -= index & -index
            return res

