def solve(nums, k):
    from collections import defaultdict

    graph = defaultdict(set)
    in_degree = defaultdict(int)
    value_map = {}
    value_count = defaultdict(int)

    node_count = 0
    for i, num in enumerate(nums):
        if num not in value_map:
            value_map[num] = node_count
            node_count += 1
        val_node = value_map[num]
        value_count[val_node] += 1

    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] != nums[j]:
                graph[nums[i]].add(nums[j])
                in_degree[nums[j]] += 1

    queue = [v for v in value_map if in_degree[v] == 0]
    result = []
    while queue:
        node = queue.pop(0)
        result.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)
    result.sort()
    total = 0
    for val in result:
        total += value_count[val]
        if total >= k:
            return val

