class OrderStatisticTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        self.root = self._insert(self.root, value)

    def _insert(self, node, value):
        if not node:
            return Node(value)
        if value == node.value:
            node.count += 1
            return node
        if value < node.value:
            node.left = self._insert(node.left, value)
            node.left_size += 1
        else:
            node.right = self._insert(node.right, value)
        return node

    def find_kth(self, k):
        return self._find_kth(self.root, k)

    def _find_kth(self, node, k):
        if not node:
            return None
        left_size = node.left_size if node.left else 0
        if k <= left_size:
            return self._find_kth(node.left, k)
        elif k <= left_size + node.count:
            return node.value
        else:
            return self._find_kth(node.right, k - left_size - node.count)

