    from collections import Counter
    sorted_unique = sorted(set(nums))
    freq = Counter(nums)

    def count_less_or_equal(x):
        total = 0
        for val in sorted_unique:
            if val <= x:
                total += freq[val]
            else:
                break
        return total

    left, right = sorted_unique[0], sorted_unique[-1]
    while left < right:
        mid = (left + right) // 2
        cnt = count_less_or_equal(mid)
        if cnt < k:
            left = mid + 1
        else:
            right = mid
    return left

