def solve(nums, k):
    def count_and_find_kth(arr, k):
        if len(arr) == 1:
            return arr[0]
        mid = len(arr) // 2
        left = arr[:mid]
        right = arr[mid:]

        left_count = len(left)
        right_count = len(right)
        i = j = 0
        merged = []
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                j += 1
            if i < len(left) and left[i] <= right[j]:
                left_count -= 1
            else:
                right_count -= 1
            if left_count == k:
                return left[i]
            if right_count == k:
                return right[j]
        while i < len(left):
            merged.append(left[i])
            i += 1
            if left_count == k:
                return left[i-1]
        while j < len(right):
            merged.append(right[j])
            j += 1
            if right_count == k:
                return right[j-1]
        return merged[-1]

    return count_and_find_kth(sorted(nums), k)

