# Idea: Use a recursive divide and conquer approach that partitions the array based on a pivot and counts elements less than or equal to the pivot to determine the k-th smallest.
def solve(nums, k):
    def count_less_equal(arr, pivot):
        count = 0
        for num in arr:
            if num <= pivot:
                count += 1
        return count

    def partition(arr, pivot):
        left = []
        right = []
        equal = []
        for num in arr:
            if num < pivot:
                left.append(num)
            elif num == pivot:
                equal.append(num)
            else:
                right.append(num)
        return left, equal, right

    def find_kth_smallest(arr, k):
        if len(arr) == 1:
            return arr[0]
        pivot = arr[len(arr) // 2]
        left, equal, right = partition(arr, pivot)
        if k <= len(left):
            return find_kth_smallest(left, k)
        elif k <= len(left) + len(equal):
            return pivot
        else:
            return find_kth_smallest(right, k - len(left) - len(equal))

    return find_kth_smallest(nums, k)

