import random

def solve(nums, k):
    def partition(arr, left, right, pivot):
        while left <= right:
            while arr[left] < pivot:
                left += 1
            while arr[right] > pivot:
                right -= 1
            if left <= right:
                arr[left], arr[right] = arr[right], arr[left]
                left += 1
                right -= 1
        return left

    def select(arr, k):
        left, right = 0, len(arr) - 1
        while left <= right:
            pivot_idx = random.randint(left, right)
            pivot = arr[pivot_idx]
            pivot_idx = partition(arr, left, right, pivot)
            if pivot_idx == k:
                return pivot
            elif pivot_idx < k:
                left = pivot_idx + 1
            else:
                right = pivot_idx - 1
        return arr[left]

    return select(nums, k - 1)

