def solve(nums, k):
    min_val = min(nums)
    max_val = max(nums)
    bucket_size = (max_val - min_val) // 200 + 1
    buckets = [0] * (bucket_size + 1)

    for num in nums:
        index = (num - min_val) // bucket_size
        if index >= len(buckets):
            index = len(buckets) - 1
        buckets[index] += 1

    for i in range(len(buckets)):
        if buckets[i] >= k:
            return min_val + i * bucket_size
        k -= buckets[i]

    return min_val + len(buckets) * bucket_size

